            else{Need(draws.Length==1,"Exactly one real victim Draw entity is recorded.");var draw=draws.Single();Need(E<BaoXinYimouDrawIssuedEvent>(g).Count(e=>e.FrameId==frame.Id&&e.VictimSeat==victim)==1&&draw.From==CardLocation.DrawPile&&draw.To==CardLocation.Hand(victim)&&draw.Sequence>gift.Sequence,"After every gift child, exactly one real victim Draw1 returns through its original damage window.");if(scene=="yimou-paid-loss")Need(!Has(g,0,Yimou),"A genuine source loss inside the paid gift subtree does not revoke its living victim's native draw.");if(scene=="yimou-reshuffle")Need(g.CardMovements.Any(m=>m.Reason==CardMoveReasons.Reshuffle&&m.Sequence>gift.Sequence&&m.Sequence<draw.Sequence)&&E<BaoXinMovementPaidEvent>(g).Single(e=>e.FrameId==frame.Id&&e.Stage==BaoXinStage.DrawChildren).Count==1,"A true empty-deck reshuffle is separate from the one actual Draw entity, and both native movement batches settle before return.");}
