    private static PlayerSnapshot V(GameEngine g,int s)=>g.CreateSnapshot(s).Players[s];
    private static bool Has(GameEngine g,int s,string skill)=>V(g,s).Skills!.Any(x=>x.Id==skill);
    private static T[] E<T>(GameEngine g)where T:IGameEvent=>g.Events.Select(e=>e.Payload).OfType<T>().ToArray();
    private static PendingDecision? P(GameEngine g)=>Enumerable.Range(0,4).Select(s=>g.CreateSnapshot(s).PendingDecision).FirstOrDefault(p=>p is not null);
    private static ProgramSkillFrame Own(GameEngine g)=>g.ResolutionStack.OfType<ProgramSkillFrame>().Single(f=>f.BaoXin is not null);
    private static int[] PublicPile(GameEngine g,int viewer,int holder){var p=g.CreateSnapshot(viewer).Players[holder];return p.PublicPersistentPiles is{}piles?piles.Where(x=>x.SourceSkillId==Mutao).SelectMany(x=>x.Cards).Select(c=>c.Id).ToArray():p.PublicPersistentPileSkillId==Mutao?p.PublicPersistentPileCards?.Select(c=>c.Id).ToArray()??[]:[];}
    private static bool Branch(GameEngine g,string b)=>P(g)?.Choices.Any(c=>c.Parameters.GetValueOrDefault("program-action")=="bao-xin"&&c.Parameters.GetValueOrDefault("branch")==b)==true;
